//! 🧪️ Actual document fixtures, owned geometry, bounded work and private publication.
use super::*;
use crate::schema::scene_preparation::{DocumentSceneJob,DocumentSceneLimits,DocumentRasterJob,DocumentSceneViewport,DocumentAlgorithmLimits};
use serde_json::{Value,json};
fn rows()->Vec<Value>{serde_json::from_str(include_str!("../../🧫️fixtures/🔣️.json")).unwrap()}
fn limits(v:&Value)->DocumentBooleanLimits{DocumentBooleanLimits{tolerance:v["tolerance"].as_f64().unwrap(),epsilon:v["epsilon"].as_f64().unwrap(),max_depth:v["maxDepth"].as_u64().unwrap()as usize,max_references:v["maxReferences"].as_u64().unwrap()as usize,max_edges:v["maxEdges"].as_u64().unwrap()as usize,max_parameters:v["maxParameters"].as_u64().unwrap()as usize,max_atomic_edges:v["maxAtomicEdges"].as_u64().unwrap()as usize,max_segments:v["maxSegments"].as_u64().unwrap()as usize,max_retained_segments:v["maxRetainedSegments"].as_u64().unwrap()as usize,max_work:v["maxWork"].as_u64().unwrap()}}
fn preparation(v:&Value)->DocumentSceneLimits{DocumentSceneLimits{max_nodes:v["maxNodes"].as_u64().unwrap()as usize,max_depth:v["maxDepth"].as_u64().unwrap()as usize,max_segments:v["maxSegments"].as_u64().unwrap()as usize,max_references:v["maxReferences"].as_u64().unwrap()as usize,max_source_bytes:v["maxSourceBytes"].as_u64().unwrap()as usize}}
fn input(row:&Value)->DocumentBooleanInput{let document:crate::DrawingSnapshot=serde_json::from_value(row["document"].clone()).unwrap();let mut job=DocumentSceneJob::new(&document,preparation(&row["preparation"])).unwrap();while !job.advance(4096).unwrap().done{}DocumentBooleanInput{plan:job.result().unwrap(),limits:limits(&row["limits"])}}
fn output(plan:&DocumentScenePlan)->Value{json!({"nodes":plan.nodes.iter().map(|n|{let c=match &n.content{DocumentSceneContent::Path{segments,fill_rule,fill,stroke}=>json!({"kind":"path","segments":segments,"fillRule":fill_rule,"fill":fill,"stroke":stroke}),DocumentSceneContent::Group{children,isolation}=>json!({"kind":"group","children":children,"isolation":isolation}),_=>panic!("Unexpected fixture content")};json!({"id":n.id,"groups":n.groups.iter().map(|g|json!({"id":g.id,"opacity":g.opacity,"blendMode":g.blend_mode})).collect::<Vec<_>>(),"transform":n.transform,"visible":n.visible,"opacity":n.opacity,"blendMode":n.blend_mode,"content":c})}).collect::<Vec<_>>()})}
fn finish(input:DocumentBooleanInput,grant:usize)->(DocumentScenePlan,DocumentBooleanProgress){let mut job=DocumentBooleanJob::new(input).unwrap();assert!(matches!(job.result(),Err(DocumentSceneError::Incomplete)));let(mut work,mut resolved)=(0,0);loop{let p=job.advance(grant).unwrap();assert!(p.work-work<=grant as u64);assert!(p.resolved>=resolved);work=p.work;resolved=p.resolved;if p.done{return(job.into_result().unwrap(),p);}assert!(matches!(job.result(),Err(DocumentSceneError::Incomplete)));}}
fn area(segments:&[DrawingSegment])->f64{let(mut origin,mut previous,mut sum)=([0.0;2],[0.0;2],0.0);for s in segments{match s{DrawingSegment::Move{to}=>{origin=*to;previous=*to},DrawingSegment::Line{to}=>{sum+=((previous[0]-origin[0])*(to[1]-origin[1])-(previous[1]-origin[1])*(to[0]-origin[0]))/2.0;previous=*to},DrawingSegment::Close=>{},_=>panic!("Unresolved curve")}}sum.abs()}
#[test]
fn painted_scenes_actual_boolean_documents_have_stable_filled_results(){
 for row in rows(){let source=input(&row);let mut previous=None;for grant in [1,7,4096]{let(plan,p)=finish(source.clone(),grant);let node=plan.nodes.iter().find(|n|n.id=="result").unwrap();let DocumentSceneContent::Path{segments,..}=&node.content else{panic!("Unresolved Boolean result")};assert_eq!(segments.iter().filter(|s|matches!(s,DrawingSegment::Move{..})).count(),row["expected"]["contours"].as_u64().unwrap()as usize);assert!((area(segments)-row["expected"]["area"].as_f64().unwrap()).abs()<=row["expected"]["tolerance"].as_f64().unwrap_or(1e-8));let actual=output(&plan);if let Some(before)=previous{assert_eq!(before,actual);}previous=Some(actual);println!("[DEBUG] Native complete Boolean document {} grant={grant} work={} retained={}",row["name"],p.work,p.segments);}}
}
#[test]
fn painted_scenes_boolean_dependencies_caps_and_failures_are_private(){
 let source=input(&rows()[0]);for kind in 0..3{let mut value=source.clone();match kind{0=>value.limits.max_work=0,1=>value.limits.max_depth=0,_=>value.limits.max_retained_segments=0}assert!(DocumentBooleanJob::new(value).is_err());}
 for kind in 0..8{let mut value=source.clone();match kind{0=>{let DocumentSceneContent::Boolean{children,..}=&mut value.plan.nodes.last_mut().unwrap().content else{panic!()};*children=vec!["absent".into()]},1=>{let DocumentSceneContent::Boolean{children,..}=&mut value.plan.nodes.last_mut().unwrap().content else{panic!()};*children=vec!["result".into()]},2=>value.plan.nodes[0].content=DocumentSceneContent::Image{asset:"x".into(),width:1.0,height:1.0},3=>value.plan.nodes[0].id="result".into(),4=>value.limits.max_depth=1,5=>value.limits.max_references=1,6=>value.limits.max_retained_segments=1,_=>value.limits.max_work=1}
  let mut job=DocumentBooleanJob::new(value).unwrap();let error=job.advance(10000000).unwrap_err();assert_eq!(job.advance(1).unwrap_err(),error);assert_eq!(job.result().unwrap_err(),error);}
 assert!(DocumentBooleanJob::new(source).unwrap().advance(0).is_err());
}
#[test]
fn painted_scenes_boolean_cancels_every_phase_and_owned_plans_survive(){
 let source=input(&rows()[0]);let mut probe=DocumentBooleanJob::new(source.clone()).unwrap();let mut seen=BTreeSet::new();loop{let p=probe.advance(1).unwrap();if seen.insert(p.phase){let mut job=DocumentBooleanJob::new(source.clone()).unwrap();job.advance(p.work as usize).unwrap();job.cancel();assert!(matches!(job.result(),Err(DocumentSceneError::Cancelled)));assert!(matches!(job.advance(1),Err(DocumentSceneError::Cancelled)));}if p.done{break;}}
 assert_eq!(seen,BTreeSet::from(["indexing","validation","cycles","requirements","traversal","operands","geometry","remapping","publishing","complete"]));let mut job=DocumentBooleanJob::new(source).unwrap();while !job.advance(4096).unwrap().done{}let published=job.result().unwrap().clone();job.cancel();assert_eq!(published.nodes.len(),3);
}
#[test]
fn painted_scenes_boolean_exact_retention_and_work_caps_publish_same_plan(){
 let source=input(&rows()[0]);let(expected,p)=finish(source.clone(),1);let mut exact=source;exact.limits.max_work=p.work;exact.limits.max_retained_segments=p.segments;assert_eq!(output(&finish(exact,7).0),output(&expected));
}
#[test]
fn painted_scenes_boolean_accuracy_refuses_privately_and_empty_singular_results_stay_empty(){
 let mut value=input(&rows()[0]);value.plan.nodes.last_mut().unwrap().transform=[1e8,0.0,0.0,1e8,0.0,0.0];let mut job=DocumentBooleanJob::new(value).unwrap();let error=job.advance(10000000).unwrap_err();assert!(error.to_string().contains("precision"));assert_eq!(job.result().unwrap_err(),error);
 let mut empty=input(&rows()[8]);let DocumentSceneContent::Boolean{reference_transform,..}=&mut empty.plan.nodes.last_mut().unwrap().content else{panic!()};*reference_transform=[0.0;6];let(plan,_)=finish(empty,7);let DocumentSceneContent::Path{segments,..}=&plan.nodes.last().unwrap().content else{panic!()};assert!(segments.is_empty());
}
fn viewport()->DocumentSceneViewport{DocumentSceneViewport{width:64,height:48,origin:[-32.0,-8.0],tolerance:0.005,max_pixels:100000,max_source_bytes:100000,max_bytes:100000,max_chunks:100}}
#[test]
fn painted_scenes_actual_boolean_raster_jobs_forward_partial_geometry(){
 for row in rows(){let document:crate::DrawingSnapshot=serde_json::from_value(row["document"].clone()).unwrap();for grant in [1,7,4096]{let mut job=DocumentRasterJob::new(&document,preparation(&row["preparation"]),viewport(),DocumentAlgorithmLimits{max_work:10000000,booleans:limits(&row["limits"]),trace:crate::schema::scene_trace::DocumentTraceLimits{max_pixels:100000,max_decoded_pixels:100000,max_source_bytes:100000,max_bytes:100000,max_chunks:100,max_edges:65536,max_segments:65536,max_retained_segments:65536,max_work:10000000}}).unwrap();let(mut work,mut partial)=(0,false);loop{let p=job.advance(grant).unwrap();assert!(p.work-work<=grant as u64);work=p.work;if p.resolution.and_then(|p|p.geometry).is_some_and(|p|!p.done){partial=true;assert!(matches!(job.result(),Err(DocumentSceneError::Incomplete)));}if p.done{break;}}assert_eq!(job.result().unwrap().pixels.len(),64*48*4);if grant==1{assert!(partial);}}}
}

#[test]
fn document_boolean_retirement_composes_child_and_private_scene_owners(){
 use crate::schema::scene_retirement::ScenePlanCloseJob;
 let fixtures:Value=serde_json::from_str(include_str!("../../🧫️fixtures/🧹️retirement/🔣️.json")).unwrap();
 for sample in fixtures["cases"].as_array().unwrap(){for grant in [1,7,4096]{let row=rows().into_iter().find(|r|r["name"]==*sample.get("source").unwrap_or(&fixtures["source"])).unwrap();let mut source=input(&row);let m=&fixtures["metadata"];for n in &mut source.plan.nodes{n.groups=vec![crate::schema::DrawingSceneGroup{id:m["group"]["id"].as_str().unwrap().into(),opacity:m["group"]["opacity"].as_f64().unwrap(),blend_mode:m["group"]["blendMode"].as_str().unwrap().into()}];}let DocumentSceneContent::Boolean{fill,stroke,..}=&mut source.plan.nodes.last_mut().unwrap().content else{panic!()};*fill=Some(serde_json::from_value(m["fill"].clone()).unwrap());*stroke=Some(serde_json::from_value(m["stroke"].clone()).unwrap());source.plan.assets=vec![crate::schema::scene_raster::RasterSceneAsset{id:m["asset"]["id"].as_str().unwrap().into(),mime:m["asset"]["mime"].as_str().unwrap().into(),data:std::sync::Arc::new(m["asset"]["data"].as_str().unwrap().into())}];
  if let Some(n)=sample["maxWork"].as_u64(){source.limits.max_work=n;}if let Some(n)=sample["maxRetainedSegments"].as_u64(){source.limits.max_retained_segments=n as usize;}let source_ptr=source.plan.nodes.as_ptr();let mut job=DocumentBooleanJob::new(source).unwrap();let phase=sample["phase"].as_str().unwrap();
  if phase=="failure"{assert!(job.advance(100000).is_err());if sample["maxWork"].is_number(){assert!(!job.ids.is_empty());}}else if phase!="fresh"{if phase!="cancelled"{let mut reached=false;for _ in 0..100000{if job.advance(1).unwrap().phase==phase{reached=true;break;}}assert!(reached);}for _ in 0..sample["offset"].as_u64().unwrap(){job.advance(1).unwrap();}}
  if phase=="cancelled"{job.cancel();}let published=if phase=="complete"{Some(job.result().unwrap().nodes.as_ptr())}else{None};let(mut close,input,output)=job.into_retirement();if let Some(ptr)=published{assert!(input.nodes.is_empty());assert_eq!(output.as_ref().unwrap().nodes.as_ptr(),ptr);let mut output_close=ScenePlanCloseJob::new(output.unwrap());while !output_close.advance(grant).unwrap().done{}}else{assert!(output.is_none());if phase!="cancelled"{assert_eq!(input.nodes.as_ptr(),source_ptr);}}
  assert!(close.advance(0).is_err());let mut work=0;loop{let before=close.job.as_ref().map_or(0,|j|j.operands.len());let p=close.advance(grant).unwrap();let after=close.job.as_ref().map_or(0,|j|j.operands.len());assert!(before-after<=grant);assert!(p.work>work&&p.work-work<=grant as u64);work=p.work;if p.done{break;}}assert!(work>=fixtures["minimumWork"].as_u64().unwrap());assert!(close.terminal_is_empty());assert!(close.job.is_none());let p=close.advance(1).unwrap();assert_eq!((p.phase,p.work,p.done),("complete",work,true));let mut input_close=ScenePlanCloseJob::new(input);while !input_close.advance(grant).unwrap().done{}println!("[DEBUG] Native document Boolean {phase} composed and retired private owners in {work} work units at grant {grant}");
 }}
}
